#define MIC_PIN 4
#define LED_PIN 48

int noiseFloor = 0;
int threshold = 0;

int readMic() {
  long sum = 0;
  for (int i = 0; i < 16; i++) {
    sum += analogRead(MIC_PIN);
    delayMicroseconds(200);
  }
  return sum / 16;
}

void setColor(int r, int g, int b) {
  neopixelWrite(LED_PIN, r, g, b);
}

void setup() {
  analogReadResolution(12);

  setColor(0, 0, 0);

  delay(300);
  long sum = 0;
  for (int i = 0; i < 100; i++) {
    sum += readMic();
    delay(10);
  }
  noiseFloor = sum / 100;
  threshold = noiseFloor + 400;

  setColor(255, 0, 0);
}

void loop() {
  int level = readMic();

  if (level > threshold) {
    setColor(0, 255, 0);   // громко — зелёный
  } else {
    setColor(255, 0, 0);   // тихо — красный
  }
}
